def check_guess(guess, target):
    if guess < target:
        return "太小啦喵"
    elif guess > target:
        return "太大啦喵"
    else:
        return "猜中啦喵！"

def play(target, picks):
    step = 0
    while True:
        guess = picks.pop(0)
        step = step + 1
        print(guess, check_guess(guess, target))
        if guess == target:
            return step

used = play(3, [1, 6, 8, 3])
print("答案是", 3, "一共猜了", used, "次喵")

